/**
 * סט האייקונים של האפליקציה - Phosphor (MIT, phosphoricons.com), גרסה 2.1.7.
 *
 * הנתונים מועתקים לכאן ולא מגיעים מחבילה, בכוונה: תלות חדשה משנה את
 * package-lock.json, וזו טביעת הקוד הנייטיבי - כלומר אייקון חדש היה
 * מחייב כל משתמש בהתקנת APK במקום עדכון חי (ראו "עדכונים" ב-CLAUDE.md).
 *
 * השמות הם שמות התפקיד באפליקציה (שנשארו מ-lucide), והמקור ב-Phosphor
 * כתוב בהערה ליד כל אחד. אייקון חדש: לוקחים מ-phosphoricons.com את
 * ה-path של שלושת המשקלים, בתיבת 256.
 *
 * שלושה משקלים ולא עובי קו חופשי:
 *   regular - ברירת המחדל. קו דק ומדויק, שמתאים לדיו על נייר.
 *   bold    - סימון קטן שצריך להיקרא במבט (וי בתיבה, פלוס בכפתור).
 *   fill    - מצב פעיל: הלשונית הנבחרת, פריט שהודלק.
 */
import { forwardRef, type SVGProps } from 'react';

export type IconWeight = 'regular' | 'bold' | 'fill';

export type IconProps = Omit<SVGProps<SVGSVGElement>, 'ref'> & {
  size?: number | string;
  weight?: IconWeight;
};

export type Icon = ReturnType<typeof make>;

const WEIGHT_INDEX: Record<IconWeight, 0 | 1 | 2> = { regular: 0, bold: 1, fill: 2 };

/** [regular, bold, fill]. כמה צורות באייקון אחד מופרדות ב-| ומצוירות כ-path נפרדים. */
type IconData = readonly [string, string, string];

function make(name: string, data: IconData) {
  const Component = forwardRef<SVGSVGElement, IconProps>(function Icon(
    { size = 24, weight = 'regular', ...rest },
    ref,
  ) {
    const paths = data[WEIGHT_INDEX[weight]].split('|');
    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        width={size}
        height={size}
        viewBox="0 0 256 256"
        fill="currentColor"
        aria-hidden={rest['aria-label'] ? undefined : true}
        focusable="false"
        {...rest}
      >
        {paths.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </svg>
    );
  });
  Component.displayName = name;
  return Component;
}

